import type { Game } from './Game';

export abstract class Screen {
  readonly el: HTMLElement;
  /** Background dim while this screen is shown (0..1). */
  backgroundDim = 0.5;
  /** Background blur in px (BackgroundScreenBeatmap.BlurAmount). */
  /** Canvases making up the screen, bottom to top, for F12 screenshots (null when the screen isn't canvas-drawn). */
  screenshotLayers?(): HTMLCanvasElement[];

  /** BackgroundScreenDefault: the main menu shows the MenuBackgroundSource background. */
  get usesMenuBackground(): boolean {
    return false;
  }

  /** Whether the global track loops while this screen shows (song select loops the preview). */
  get trackLoops(): boolean {
    return false;
  }

  /** IOsuScreen.AllowTrackControl */
  get allowTrackControl(): boolean {
    return true;
  }

  /** Whether the menu cursor is shown (the osu! ruleset provides its own cursor during gameplay). */
  get cursorVisible(): boolean {
    return true;
  }

  /** Whether the mouse wheel adjusts the volume over this screen (ScrollAdjustsVolume). */
  get scrollAdjustsVolume(): boolean {
    return false;
  }

  /** Whether unhandled wheel events are swallowed (GameplayScrollWheelHandling with MouseDisableWheel). */
  get blocksWheel(): boolean {
    return false;
  }

  /** IOsuScreen.BackgroundParallaxAmount */
  get backgroundParallaxAmount(): number {
    return 1;
  }

  get backgroundBlur(): number {
    return 0;
  }
  /** Whether the triangles background should be visible. */
  showTriangles = true;

  constructor(
    protected readonly game: Game,
    className: string,
  ) {
    this.el = document.createElement('div');
    this.el.className = `screen ${className}`;
  }

  onEnter(): void {}
  onResume(): void {}
  onSuspend(): void {}
  onExit(): void {}

  /** Return true if handled. */
  onKeyDown(_e: KeyboardEvent): boolean {
    return false;
  }

  onKeyUp(_e: KeyboardEvent): boolean {
    return false;
  }

  /** Called when the user presses back (Escape). Return false to prevent leaving. */
  onBack(): boolean {
    return true;
  }
}
